import type { PostHog } from 'posthog-js'

// Process-level singleton, mirroring the posthog-js default export which is
// itself a module-level singleton. Safe because setDefaultPostHogInstance is
// only called once at module evaluation time by src/index.ts.
let defaultPostHogInstance: PostHog | undefined

export function setDefaultPostHogInstance(instance: PostHog | undefined): void {
    defaultPostHogInstance = instance
}

export function getDefaultPostHogInstance(): PostHog | undefined {
    return defaultPostHogInstance
}
import type { PostHog } from 'posthog-js'
import type { BootstrapConfig } from 'posthog-js'
import { createContext } from 'react'
import { getDefaultPostHogInstance } from './posthog-default'

export type { PostHog }

// The getter defers evaluation so that the full bundle's setDefaultPostHogInstance()
// call (which runs after module evaluation) has already executed by the time React
// accesses the default value. In the slim bundle no default is set, so client will
// be undefined — users must always provide a <PostHogProvider client={…}>.
export const PostHogContext = createContext<{ client: PostHog; bootstrap?: BootstrapConfig }>({
    get client() {
        return getDefaultPostHogInstance() as PostHog
    },
    bootstrap: undefined,
})
// Deeply compares two objects for equality.
// Use a WeakMap to keep track of visited objects to avoid infinite recursion.
// WeakMap is supported in IE11, see https://caniuse.com/?search=JavaScript%20WeakMap

export function isDeepEqual(obj1: any, obj2: any, visited = new WeakMap()): boolean {
    if (obj1 === obj2) {
        return true
    }

    if (typeof obj1 !== 'object' || obj1 === null || typeof obj2 !== 'object' || obj2 === null) {
        return false
    }

    if (visited.has(obj1) && visited.get(obj1) === obj2) {
        return true
    }
    visited.set(obj1, obj2)

    const keys1 = Object.keys(obj1)
    const keys2 = Object.keys(obj2)

    if (keys1.length !== keys2.length) {
        return false
    }

    for (const key of keys1) {
        if (!keys2.includes(key)) {
            return false
        }
        if (!isDeepEqual(obj1[key], obj2[key], visited)) {
            return false
        }
    }

    return true
}
